-- ============================================================
-- 급여관리(sal) 모듈 + 급여 산정 엔진(calc engine) 더미 데이터 (com_id = 1 기준)
-- salary_calculation_engine_ddl.sql (신규 4개 테이블)이 반영된 것을 전제로 한다.
--
-- 이 스크립트는 [기존 더미 데이터 전체 삭제] -> [정책 테이블부터 새로 등록] -> 
-- [정책 테이블 값(요율/직책수당/소득세 구간/식대)을 실제로 참조해서 산정한 sal_pay/sal_pay_item 재등록]
-- 순서로 동작한다. 즉 06_sal_dummy_data.sql / 이전 버전 07 을 대체한다.
--
-- salary-calculation-engine-design.md / -implementation.md 의 계산 규칙을 그대로 반영:
--   MEAL_ALLOWANCE            = sal_meal_alw_plcy.amt (com_id=1 우선, 없으면 com_id=NULL 공통값)
--   POSITION_ALLOWANCE        = sal_pos_alw 에서 com_id+pos(POS_CODE) 매칭 (없으면 0)
--   ANNUAL_LEAVE_ALLOWANCE    = leave_balance(연도별)의 (total_days-used_days) x 통상일급(baseSal/209x8).
--                                09_attendance_leave_dummy_data.sql(담당자 원본, 회사 전체 46명 대상)에는 우리 12명
--                                (emp_id 132~143)의 leave_balance 행이 없어 전부 0원(신규 입사자 등 데이터 없음 -
--                                design 문서상 정상 케이스, 에러 아님)으로 산정된다.
--   OVERTIME_ALLOWANCE        = attendance.overtime_minutes 월합계 x 통상시급(baseSal/209) x 1.5 (원단위 절사).
--                                마찬가지로 우리 12명의 6~7월 attendance 행이 없어 전부 0원(근태 기록 없는 달 -
--                                정상 케이스)으로 산정된다.
--   NATIONAL_PENSION          = baseSal x sal_rate_plcy.pens_rate (원단위 절사)
--   HEALTH_INSURANCE          = baseSal x sal_rate_plcy.hlth_rate (원단위 절사)
--   LONG_TERM_CARE_INSURANCE  = 절사된 HEALTH_INSURANCE x sal_rate_plcy.care_rate (원단위 절사)
--   EMPLOYMENT_INSURANCE      = baseSal x sal_rate_plcy.empl_rate (원단위 절사)
--   INCOME_TAX                = baseSal 이 속한 sal_inc_tax_brkt 구간의 tax_rate x baseSal (원단위 절사)
--   LOCAL_INCOME_TAX          = INCOME_TAX x 10% (원단위 절사)
--
-- SalaryCalculationService 는 SalaryItemCode.values() 10개 항목을 전부 순회하며 후보를 만들어내므로,
-- sal_pay 1건당 sal_pay_item 은 항상 정확히 10건(0원인 항목 포함)이 생성된다.
-- ============================================================

SET DEFINE OFF;

-- ------------------------------------------------------------
-- 1) 기존 더미 데이터 전체 삭제 (FK 자식 -> 부모 순서)
--    sal_pay_item 은 sal_pay 삭제 시 ON DELETE CASCADE 로 이미 함께 삭제되지만,
--    스크립트 재실행 안전성을 위해 명시적으로도 지운다.
-- ------------------------------------------------------------
DELETE FROM sal_hist;
DELETE FROM sal_pay_item;
DELETE FROM sal_pay;
DELETE FROM sal_acct;
DELETE FROM sal_std;
DELETE FROM sal_meal_alw_plcy;
DELETE FROM sal_pos_alw;
DELETE FROM sal_inc_tax_brkt;
DELETE FROM sal_rate_plcy;

-- ------------------------------------------------------------
-- 2) 시퀀스 초기화 (DROP -> CREATE, 테이블 구조는 건드리지 않고 시퀀스만 1부터 재시작)
-- ------------------------------------------------------------
BEGIN EXECUTE IMMEDIATE 'DROP SEQUENCE sal_std_seq'; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -2289 THEN RAISE; END IF; END;
/
CREATE SEQUENCE sal_std_seq START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
BEGIN EXECUTE IMMEDIATE 'DROP SEQUENCE sal_acct_seq'; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -2289 THEN RAISE; END IF; END;
/
CREATE SEQUENCE sal_acct_seq START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
BEGIN EXECUTE IMMEDIATE 'DROP SEQUENCE sal_pay_seq'; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -2289 THEN RAISE; END IF; END;
/
CREATE SEQUENCE sal_pay_seq START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
BEGIN EXECUTE IMMEDIATE 'DROP SEQUENCE sal_pay_item_seq'; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -2289 THEN RAISE; END IF; END;
/
CREATE SEQUENCE sal_pay_item_seq START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
BEGIN EXECUTE IMMEDIATE 'DROP SEQUENCE sal_hist_seq'; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -2289 THEN RAISE; END IF; END;
/
CREATE SEQUENCE sal_hist_seq START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
BEGIN EXECUTE IMMEDIATE 'DROP SEQUENCE sal_rate_plcy_seq'; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -2289 THEN RAISE; END IF; END;
/
CREATE SEQUENCE sal_rate_plcy_seq START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
BEGIN EXECUTE IMMEDIATE 'DROP SEQUENCE sal_pos_alw_seq'; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -2289 THEN RAISE; END IF; END;
/
CREATE SEQUENCE sal_pos_alw_seq START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
BEGIN EXECUTE IMMEDIATE 'DROP SEQUENCE sal_inc_tax_brkt_seq'; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -2289 THEN RAISE; END IF; END;
/
CREATE SEQUENCE sal_inc_tax_brkt_seq START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;
BEGIN EXECUTE IMMEDIATE 'DROP SEQUENCE sal_meal_alw_plcy_seq'; EXCEPTION WHEN OTHERS THEN IF SQLCODE != -2289 THEN RAISE; END IF; END;
/
CREATE SEQUENCE sal_meal_alw_plcy_seq START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;

-- ------------------------------------------------------------
-- 3) sal_rate_plcy : 4대보험 요율 정책 (comId 없음, 전국 공통) - 2건
--    2026년 현재 유효한 1건만 실제 계산에 쓰인다. 2025년은 종료된 이력 예시.
-- ------------------------------------------------------------

-- ------------------------------------------------------------
-- 4) sal_pos_alw : 직책별 수당 (com_id=1) - 5건
--    사원(P1)/주임(P2)/대리(P3)는 직책수당 정책이 없음(= 0원, 정책 미존재).
-- ------------------------------------------------------------

-- ------------------------------------------------------------
-- 5) sal_inc_tax_brkt : 소득세 근사 구간표 (comId 없음, 전국 공통) - 10건
--    2026년 5개 구간이 현재 유효. 2025년 5개 구간은 종료된 이력 예시.
--    (부양가족 수 미반영, 포트폴리오/데모용 단순 정률 근사치)
-- ------------------------------------------------------------

-- ------------------------------------------------------------
-- 6) sal_meal_alw_plcy : 식대 정책 - 3건
--    com_id=1 전용 정책이 있으므로 실제 계산에는 2번 행(20만원)이 쓰이고,
--    1번 행(comId NULL, 15만원)은 comId 지정 정책이 없는 다른 회사를 위한 전사 공통 fallback 예시.
-- ------------------------------------------------------------

-- ------------------------------------------------------------
-- 7) sal_std (급여기준) : 12명 x 1건 + 승진 2명 x 버저닝 2건 = 14건
-- ------------------------------------------------------------

-- ------------------------------------------------------------
-- 8) sal_acct (급여 수령 계좌) : 12명 x 1건
-- ------------------------------------------------------------

-- ------------------------------------------------------------
-- 9) sal_pay (급여 지급) : 6월 6건 + 7월 12건 = 18건
--    OVERTIME_ALLOWANCE/ANNUAL_LEAVE_ALLOWANCE 는 09_attendance_leave_dummy_data.sql 에 우리 12명의
--    6~7월 근태/연차 데이터가 없어 전부 0원이다 (데이터 없음 = 정상 케이스, 에러 아님).
-- ------------------------------------------------------------

-- ------------------------------------------------------------
-- 10) sal_pay_item (급여 지급 세부 항목) : 180건 (18건 x 10개 항목, 0원 항목 포함)
-- ------------------------------------------------------------

-- ------------------------------------------------------------
-- 11) sal_hist (급여 변경이력) : 12건
-- ------------------------------------------------------------

COMMIT;